"use client";
import type { CSSProperties, ReactNode } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";
export interface AnimatedIconButtonProps extends AnimationButtonProps {
  icon?: ReactNode;
  hoverIcon?: ReactNode;
  iconSize?: number;
}
const css = `
.z-anb-icon{min-height:60px;padding:12px 12px 12px 32px;gap:16px;overflow:hidden;font-size:17.6px;font-weight:400;font-family:Arial,sans-serif}
.z-anb-icon-window{position:relative;z-index:2;flex:0 0 36px;width:36px;height:36px;display:grid;place-items:center}
.z-anb-icon-clip{position:relative;width:var(--z-anb-icon-size,20px);height:var(--z-anb-icon-size,20px);overflow:hidden}
.z-anb-icon-first,.z-anb-icon-second{position:absolute;inset:0;display:grid;place-items:center;transition:transform var(--z-anb-duration) var(--z-anb-easing)}
.z-anb-icon-first svg,.z-anb-icon-second svg{width:100%;height:100%}.z-anb-icon-second{transform:translate(-100%,100%)}
.z-anb-icon[data-active=true] .z-anb-icon-first{transform:translate(100%,-100%)}.z-anb-icon[data-active=true] .z-anb-icon-second{transform:translate(0,0)}
.z-anb-icon-fill{position:absolute;right:12px;top:calc(50% - 18px);width:36px;height:36px;z-index:0;border-radius:9999px;background:var(--z-anb-fill);transform:scale(1);transition:transform var(--z-anb-duration) var(--z-anb-easing);pointer-events:none}
.z-anb-icon[data-active=true] .z-anb-icon-fill{transform:scale(var(--z-anb-icon-expand,10),5)}
`;
const arrow = (
  <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
    <path
      d="M6 14 14 6M6 6h8v8"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);
/** A circular icon background fills the capsule as two icons cycle diagonally. */
export function AnimatedIconButton({
  children = "Shop Now",
  icon = arrow,
  hoverIcon = icon,
  iconSize = 20,
  duration = 0.5,
  easing = "linear(0,.0008 10%,.0128 20%,.0648 30%,.2048 40%,.5 50%,.7952 60%,.9352 70%,.9872 80%,.9992 90%,1)",
  ...props
}: AnimatedIconButtonProps) {
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        variant="icon"
        variables={
          {
            ...buttonVariables({ ...props, duration, easing }),
            "--z-anb-icon-size": `${Math.max(12, iconSize)}px`,
          } as CSSProperties
        }
        onEngage={(element) =>
          element.style.setProperty(
            "--z-anb-icon-expand",
            String(Math.max(10, element.offsetWidth / 18)),
          )
        }
      >
        <span className="z-anb-icon-fill" aria-hidden="true" />
        <span className="z-anb-label">{children}</span>
        <span className="z-anb-icon-window" aria-hidden="true">
          <span className="z-anb-icon-clip">
            <span className="z-anb-icon-first">{icon}</span>
            <span className="z-anb-icon-second">{hoverIcon}</span>
          </span>
        </span>
      </ButtonSurface>
    </>
  );
}
